#!/bin/bash
# 28_music_rank_capsule.sh
# 排行榜精修：右上角榜单名胶囊背景加深（surfaceVariant 50%），真机可见
set -e
cd "$(dirname "$0")/../.." 2>/dev/null || true
BASE="avbox"
RANK_KT="$BASE/app/src/main/java/com/github/tvbox/osc/ui/music/rank/RankScreen.kt"

if [ -f "$RANK_KT" ] && grep -q "surfaceVariant.copy(alpha = 0.5f)" "$RANK_KT" 2>/dev/null; then
  echo "跳过（RankScreen.kt 胶囊加深版已写入）"
  exit 0
fi

mkdir -p "$(dirname "$RANK_KT")"
echo "" | base64 -d > "$RANK_KT"
echo "已写入 rank/RankScreen.kt（胶囊加深版）"
